commands:
pwsh -NoLogo -NoProfile -Command '
$files = @("./api/_lib/pantry-store.ps1","./api/_lib/pantry-render.ps1","./podex.ps1")
foreach ($f in $files) {
  $tokens=$null;$errs=$null
  [System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path $f), [ref]$tokens, [ref]$errs) | Out-Null
  if ($errs.Count -gt 0) { Write-Host "FAIL $f"; $errs | ForEach-Object { Write-Host "  $($_.Message) @ $($_.Extent.StartLineNumber)" } }
  else { Write-Host "OK   $f" }
}'

pwsh -NoLogo -NoProfile -Command '
if (-not (Get-Module -ListAvailable PSScriptAnalyzer)) { Write-Host "PSScriptAnalyzer not available"; exit 0 }
Import-Module PSScriptAnalyzer
$files = @("./api/_lib/pantry-store.ps1","./api/_lib/pantry-render.ps1","./podex.ps1")
foreach ($f in $files) {
  $r = Invoke-ScriptAnalyzer -Path $f
  Write-Host "=== $f : $($r.Count) findings ==="
  $r | Group-Object RuleName | ForEach-Object { Write-Host ("  {0} x{1}" -f $_.Name, $_.Count) }
}'
